import{_ as a,o as r,c as n,a2 as o}from"./chunks/framework.DaGSOal_.js";const h=JSON.parse('{"title":"O","description":"","frontmatter":{},"headers":[],"relativePath":"glossaire-a-z/o.md","filePath":"glossaire-a-z/o.md"}'),s={name:"glossaire-a-z/o.md"};function t(i,e,c,l,u,d){return r(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="o" tabindex="-1">O <a class="header-anchor" href="#o" aria-label="Permalink to &quot;O&quot;">​</a></h1><h2 id="off-chain-fr-hors-chaine" tabindex="-1">Off-Chain (fr : Hors chaîne) <a class="header-anchor" href="#off-chain-fr-hors-chaine" aria-label="Permalink to &quot;Off-Chain (fr : Hors chaîne)&quot;">​</a></h2><p>Désigne les activités, données ou transactions qui se déroulent en dehors de la blockchain principale. Elles peuvent notamment passer par des solutions de couche 2, des chaînes latérales ou d’autres mécanismes qui n’effectuent pas directement les opérations sur la chaîne sous-jacente.</p><h2 id="on-chain-fr-sur-chaine" tabindex="-1">On-Chain (fr : Sur chaîne) <a class="header-anchor" href="#on-chain-fr-sur-chaine" aria-label="Permalink to &quot;On-Chain (fr : Sur chaîne)&quot;">​</a></h2><p>Désigne les activités, données ou transactions enregistrées ou exécutées directement sur la blockchain. Cela comprend notamment les transactions, l’exécution de contrats intelligents et les données stockées dans le registre de la chaîne.</p><h2 id="on-chain-governance-fr-gouvernance-sur-chaine" tabindex="-1">On-Chain Governance (fr : Gouvernance sur chaîne) <a class="header-anchor" href="#on-chain-governance-fr-gouvernance-sur-chaine" aria-label="Permalink to &quot;On-Chain Governance (fr : Gouvernance sur chaîne)&quot;">​</a></h2><p>Un système dans lequel les participants à une blockchain prennent des décisions au moyen de mécanismes de vote enregistrés sur la chaîne et régis par le protocole. Les propositions, les votes et les résultats sont traçables sur la blockchain, ce qui permet de vérifier les décisions de gouvernance, notamment celles portant sur les mises à niveau du protocole, les paramètres et l’allocation des fonds.</p><h2 id="open-source-fr-code-source-ouvert" tabindex="-1">Open Source (fr : Code source ouvert) <a class="header-anchor" href="#open-source-fr-code-source-ouvert" aria-label="Permalink to &quot;Open Source (fr : Code source ouvert)&quot;">​</a></h2><p>Désigne un logiciel dont le code source est accessible au public et peut être utilisé, modifié et redistribué conformément à sa licence. Les infrastructures fondamentales de Cardano, notamment son logiciel de nœud et ses outils de développement de contrats intelligents, sont développées selon des principes open source.</p><h2 id="operational-certificate-fr-certificat-operationnel" tabindex="-1">Operational Certificate (fr : Certificat opérationnel) <a class="header-anchor" href="#operational-certificate-fr-certificat-operationnel" aria-label="Permalink to &quot;Operational Certificate (fr : Certificat opérationnel)&quot;">​</a></h2><p>Un certificat signé par l’opérateur d’un pool de staking pour autoriser une clé KES (<em>Key Evolving Signatures</em>) à produire des blocs au nom du pool.</p><h2 id="oracle-fr-oracle" tabindex="-1">Oracle (fr : Oracle) <a class="header-anchor" href="#oracle-fr-oracle" aria-label="Permalink to &quot;Oracle (fr : Oracle)&quot;">​</a></h2><p>Un mécanisme qui fournit à une blockchain des données provenant du monde extérieur, afin que les contrats intelligents puissent les utiliser. Les blockchains ne pouvant généralement pas accéder directement aux informations externes, les oracles récupèrent et transmettent des données telles que des prix, des conditions météorologiques ou des événements du monde réel.</p><h2 id="ouroboros" tabindex="-1">Ouroboros <a class="header-anchor" href="#ouroboros" aria-label="Permalink to &quot;Ouroboros&quot;">​</a></h2><p>Le protocole de consensus par preuve d’enjeu (<em>Proof of Stake</em>, PoS) de Cardano, développé à partir de recherches évaluées par des pairs. Il sécurise le réseau en sélectionnant des responsables de créneau (<em>slot leaders</em>) chargés de produire les blocs en fonction de la participation au staking. La famille Ouroboros comprend plusieurs variantes, notamment Ouroboros Classic, Praos et Genesis.</p>',15)])])}const f=a(s,[["render",t]]);export{h as __pageData,f as default};
